import pandas as pd
dfs = [pd.read_parquet(f'/tmp/train-{i:05d}-of-00004.parquet') for i in range(4)]
df = pd.concat(dfs, ignore_index=True)
df = df[df['subset']=='default']
# scandinavian language codes
codes = ['dan','nor','swe','ice']
def is_sc(l):
    return any(any(c in str(x).lower() for c in codes) for x in l)
sc = df[df['language'].apply(is_sc)]
print('sc rows:', sc.shape)
# unique tasks with scandinavian languages
tasks = {}
for t, g in sc.groupby('task_name'):
    langs = set()
    for l in g['language']:
        for x in l:
            langs.add(str(x))
    tasks[t] = langs
# show tasks that are purely scandinavian
for t, langs in sorted(tasks.items()):
    print(t, langs)
